solutionCode:
sealed class Command {
    class DriveForward(val meters: Double) : Command()
    class Turn(val degrees: Double) : Command()
    object Stop : Command()
}

fun describe(command: Command): String {
    return when (command) {
        is Command.DriveForward -> "Drive forward ${command.meters} meters"
        is Command.Turn -> "Turn ${command.degrees} degrees"
        is Command.Stop -> "Stop the robot"
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testDriveForward() {
        Assert.assertEquals("Drive forward 3.0 meters", describe(Command.DriveForward(3.0)))
    }

    @Test
    fun testTurn() {
        Assert.assertEquals("Turn 90.0 degrees", describe(Command.Turn(90.0)))
    }

    @Test
    fun testStop() {
        Assert.assertEquals("Stop the robot", describe(Command.Stop))
    }

    @Test
    fun testDriveForwardProperty() {
        val cmd = Command.DriveForward(2.5)
        Assert.assertEquals(2.5, cmd.meters, 0.001)
    }

    @Test
    fun testTurnProperty() {
        val cmd = Command.Turn(45.0)
        Assert.assertEquals(45.0, cmd.degrees, 0.001)
    }
}
